-- 业务定价脚本
CREATE TABLE `proj_pricing_aoc_price` (
                                          `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id	',
                                          `project_id` bigint(20) NOT NULL COMMENT '所属项目ID',
                                          `apply_credit_amount` bigint(20) DEFAULT NULL COMMENT '申报授信金额',
                                          `aoc_credit_term` int(11) DEFAULT NULL COMMENT '转让额度有效期（月',
                                          `repay_type` varchar(20) DEFAULT NULL COMMENT '还款方式。间接还款：indirect、直接还款：direct',
                                          `credit_amount_loop` tinyint(1) DEFAULT NULL COMMENT '额度是否可循环',
                                          `earnest_money` bigint(20) DEFAULT NULL COMMENT '保证金',
                                          `confirmatory_party` text COMMENT '确权方',
                                          `consulting_fee` bigint(20) DEFAULT NULL COMMENT '服务费/咨询费',
                                          `aoc_financing_proportion` int(11) DEFAULT NULL COMMENT '转让融资比例',
                                          `summary` text COMMENT '拟转应收账款概述',
                                          `rate_type` varchar(10) DEFAULT NULL COMMENT '转让费率类型。固定利率：fixed、浮动利率：float	',
                                          `aoc_rate_percent` int(11) DEFAULT NULL COMMENT '转让费率值。百分之多少',
                                          `irr_percent` int(11) DEFAULT NULL COMMENT '内部收益率。百分之多少',
                                          `planned_starting_date` date DEFAULT NULL COMMENT '计划起租日',
                                          `rental_calc_type` varchar(40) DEFAULT NULL COMMENT '租金计算方式。等额租金：equivalent_rental、等额本金：equivalent_capital、平息法：pacification、不规则还款：irregular_repay\n\n其他：other',
                                          `interest_way` varchar(20) NOT NULL DEFAULT 'ACTUAL_RATE' COMMENT '利息计算方式',
                                          `create_by` bigint(20) DEFAULT NULL,
                                          `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
                                          `update_by` bigint(20) DEFAULT NULL,
                                          `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                                          `repay_rate` varchar(20) DEFAULT NULL COMMENT '还款频率',
                                          PRIMARY KEY (`id`) USING BTREE,
                                          UNIQUE KEY `uniq_project_id` (`project_id`) USING BTREE COMMENT '每个项目只能有一份报价'
) ENGINE=InnoDB AUTO_INCREMENT=195 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='项目定价-债权转让报价方案表';


