                                              `aoc_financing_proportion` int(11) DEFAULT NULL COMMENT '转让融资比例',
                                              `summary` text COMMENT '拟转应收账款概述',
                                              `rate_type` varchar(10) DEFAULT NULL COMMENT '转让费率类型。固定利率：fixed、浮动利率：float	',
                                              `aoc_rate_percent` int(11) DEFAULT NULL COMMENT '转让费率值。百分之多少',
                                              `irr_percent` int(11) DEFAULT NULL COMMENT '内部收益率。百分之多少',
                                              `planned_starting_date` date DEFAULT NULL COMMENT '计划起租日',
                                              `rental_calc_type` varchar(40) DEFAULT NULL COMMENT '租金计算方式。等额租金：equivalent_rental、等额本金：equivalent_capital、平息法：pacification、不规则还款：irregular_repay\n\n其他：other',
                                              `interest_way` varchar(20) NOT NULL DEFAULT 'ACTUAL_RATE' COMMENT '利息计算方式',
                                              `create_by` bigint(20) DEFAULT NULL,
                                              `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
                                              `update_by` bigint(20) DEFAULT NULL,
                                              `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                                              `version` varchar(40) NOT NULL COMMENT '版本号',
