CREATE TABLE `proj_pricing_lease_price` (
                                            `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id',
                                            `project_id` bigint(20) NOT NULL COMMENT '所属项目ID',
                                            `apply_credit_amount` bigint(20) DEFAULT NULL COMMENT '申报授信金额',
                                            `lease_month_count` int(11) DEFAULT NULL COMMENT '租赁期限月数',
                                            `repay_times_yearly` int(11) DEFAULT NULL COMMENT '每年还款次数',
                                            `repay_times_total` int(11) DEFAULT NULL COMMENT '还款期数',
                                            `repay_rate` varchar(20) DEFAULT NULL COMMENT '还款频率',
                                            `pay_type` varchar(20) DEFAULT NULL COMMENT '支付方式。先付：advanced、后付：afterward	',
                                            `rental_calc_type` varchar(40) DEFAULT NULL COMMENT '租金计算方式。等额租金：equivalent_rental、等额本金：equivalent_capital、平息法：pacification、不规则还款：irregular_repay\n\n其他：other',
                                            `interest_way` varchar(20) NOT NULL DEFAULT 'ACTUAL_RATE' COMMENT '利息计算方式',
                                            `credit_amount_loop` tinyint(1) DEFAULT NULL COMMENT '额度是否可循环',
                                            `earnest_money` bigint(20) DEFAULT NULL COMMENT '保证金',
                                            `down_payment` bigint(20) DEFAULT NULL COMMENT '首付款',
                                            `consulting_fee` bigint(20) DEFAULT NULL COMMENT '服务费/咨询费',
                                            `commission` bigint(20) NOT NULL DEFAULT '0' COMMENT '手续费',
                                            `first_installment_interest` bigint(20) NOT NULL DEFAULT '0' COMMENT '首期利息(元)',
                                            `nominal_price` bigint(20) DEFAULT NULL COMMENT '名义货价',
                                            `rate_type` varchar(10) DEFAULT NULL COMMENT '租赁利率类型。固定利率：fixed、浮动利率：float	',
                                            `lease_rate_percent` int(11) DEFAULT NULL COMMENT '租赁利率值。百分之多少',
                                            `irr_percent` int(11) DEFAULT NULL COMMENT '内部收益率。百分之多少',
                                            `planned_starting_date` date DEFAULT NULL COMMENT '计划起租日',
                                            `create_by` bigint(20) DEFAULT NULL COMMENT '创建人id、发起人id	',
                                            `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间。默认当前时间',
                                            `update_by` bigint(20) DEFAULT NULL COMMENT '最后更新人id	',
                                            `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间；每次记录变化，自动更新为当前时间	',
                                            PRIMARY KEY (`id`) USING BTREE,
                                            UNIQUE KEY `uniq_project_id` (`project_id`) USING BTREE COMMENT '每个立项只能有一份报价'
) ENGINE=InnoDB AUTO_INCREMENT=3231 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='项目定价-租赁报价方案表';


