CREATE TABLE `proj_pricing_base_info` (
                                          `id` bigint(20) NOT NULL AUTO_INCREMENT,
                                          `client_id` bigint(20) DEFAULT NULL COMMENT '客户id',
                                          `biz_type` varchar(20) DEFAULT NULL COMMENT '业务类型。租赁、保理、转租赁',
                                          `proj_name` varchar(200) DEFAULT NULL COMMENT '项目名称',
                                          `project_type` varchar(30) DEFAULT NULL COMMENT '下拉框选项：公共事业类、省内国（央）企、其他。\n内容决定后续审批流审批权限。\n',
                                          `project_classify` varchar(50) DEFAULT NULL COMMENT '项目分类，可选项：鼓励类，适度支持类，谨慎类，工程机械类（厂商担保模式），集团内协同业务',
                                          `regional_project_classify` varchar(50) DEFAULT NULL COMMENT '地区项目分类',
                                          `regional_division` varchar(100) DEFAULT NULL COMMENT '区域划分',
                                          `approval_type` varchar(20) DEFAULT NULL COMMENT '审批类型',
                                          `proj_code` varchar(20) DEFAULT NULL COMMENT '项目编号',
                                          `lease_types` varchar(100) DEFAULT NULL COMMENT '租赁类型。直租、回租、经营性租赁',
                                          `factoring_types` varchar(100) DEFAULT NULL COMMENT '保理类型。有追明保理、无追明保理、有追暗保理',
                                          `zr_types` varchar(100) DEFAULT NULL COMMENT '转让类型。有追、无追',
                                          `proj_source` varchar(20) DEFAULT NULL COMMENT '存量翻单、渠道介绍、自主开发',
                                          `evaluation_subject_id` bigint(20) DEFAULT NULL COMMENT '评估主体ID',
                                          `country` varchar(20) DEFAULT NULL COMMENT '国家',
                                          `province` varchar(20) DEFAULT NULL COMMENT '省份',
                                          `city` varchar(20) DEFAULT NULL COMMENT '城市',
                                          `district` varchar(20) DEFAULT NULL COMMENT '区、县',
                                          `funds_purpose` text COMMENT '资金用途',
                                          `proj_background` longtext COMMENT '项目背景',
                                          `transferor_client_id` bigint(20) DEFAULT NULL COMMENT '转让方。（项目类型为租赁时）',
                                          `lessee_info` json DEFAULT NULL COMMENT '承租人列表',
                                          `creditor_client_id` bigint(20) DEFAULT NULL COMMENT '债权人id',
                                          `creditor_stock_risk_exposure` bigint(20) DEFAULT NULL COMMENT '债权人存量风险敞口',
                                          `debtor_info` json DEFAULT NULL COMMENT '债务人信息。（项目类型为保理时）',
                                          `guarantee_info` json DEFAULT NULL COMMENT '担保人信息',
                                          `pledgor_info` json DEFAULT NULL COMMENT '质押人信息',
                                          `mortgagor_info` json DEFAULT NULL COMMENT '抵押人信息',
                                          `proj_sponsor_user_id` bigint(20) DEFAULT NULL COMMENT '项目主办用户id',
                                          `proj_cosponsor_user_ids` json DEFAULT NULL COMMENT '项目协办方用户id列表',
                                          `biz_dept_id` bigint(20) DEFAULT NULL COMMENT '业务部门id',
                                          `biz_dept_leader_id` bigint(20) DEFAULT NULL COMMENT '业务部门负责人id',
                                          `biz_division_leader_id` bigint(20) DEFAULT NULL COMMENT '业务分管领导id',
                                          `risk_control_manager_id` bigint(20) DEFAULT NULL COMMENT '风控经理id',
                                          `legal_manager_user_id` bigint(20) DEFAULT NULL,
                                          `proj_pricing_status` varchar(50) DEFAULT NULL COMMENT '定价状态',
                                          `proj_pricing_process_status` varchar(50) DEFAULT NULL COMMENT '流程状态',
                                          `declared_amount` bigint(20) DEFAULT NULL COMMENT '冗余报价方案字段',
                                          `proj_establish_id` bigint(20) DEFAULT NULL COMMENT '关联的立项ID',
                                          `create_by` bigint(20) DEFAULT NULL COMMENT '创建人、发起人',
                                          `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                          `update_by` bigint(20) DEFAULT NULL COMMENT '最后更新人id',
                                          `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                                          `creditor_info` json DEFAULT NULL COMMENT '债权人信息',
                                          `assignor` varchar(200) DEFAULT NULL COMMENT '转让方（转租赁类型时）',
                                          `relation_data_type` varchar(30) DEFAULT NULL COMMENT '数据来源类型，区分普通立项(PROJ_ESTABLISH)和集团授信(GROUP_CREDIT_REVIEW)',
                                          `group_credit_review_id` bigint(20) DEFAULT NULL COMMENT '集团授信评审id',
                                          `remark` varchar(500) DEFAULT NULL COMMENT '备注',
                                          `enterprise_nature` varchar(20) DEFAULT NULL COMMENT '企业性质',
                                          `risk_control_industry_classify` varchar(50) DEFAULT NULL COMMENT '风控行业分类',
                                          PRIMARY KEY (`id`) USING BTREE,
                                          KEY `proj_pricing_proj_sponsor_user_id` (`proj_sponsor_user_id`) USING BTREE COMMENT '主办索引',
                                          KEY `proj_pricing_base_info_relation_data_type_IDX` (`relation_data_type`,`proj_pricing_status`) USING BTREE,
                                          KEY `idx_proj_establish_id` (`proj_establish_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3888 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='项目定价基本信息表';



CREATE TABLE `proj_pricing_base_info_lib` (
                                              `id` bigint(20) NOT NULL AUTO_INCREMENT,
                                              `client_id` bigint(20) DEFAULT NULL COMMENT '客户id',
                                              `biz_type` varchar(20) DEFAULT NULL COMMENT '业务类型。租赁、保理、转租赁',
                                              `proj_name` varchar(200) DEFAULT NULL COMMENT '项目名称',
                                              `project_type` varchar(30) DEFAULT NULL COMMENT '下拉框选项：公共事业类、省内国（央）企、其他。\n内容决定后续审批流审批权限。\n',
                                              `project_classify` varchar(50) DEFAULT NULL COMMENT '项目分类，可选项：鼓励类，适度支持类，谨慎类，工程机械类（厂商担保模式），集团内协同业务',
                                              `regional_project_classify` varchar(50) DEFAULT NULL COMMENT '地区项目分类',
                                              `regional_division` varchar(100) DEFAULT NULL COMMENT '区域划分',
                                              `approval_type` varchar(20) DEFAULT NULL COMMENT '审批类型',
                                              `proj_code` varchar(20) DEFAULT NULL COMMENT '项目编号',
                                              `lease_types` varchar(100) DEFAULT NULL COMMENT '租赁类型。直租、回租、经营性租赁',
                                              `factoring_types` varchar(100) DEFAULT NULL COMMENT '保理类型。有追明保理、无追明保理、有追暗保理',
                                              `zr_types` varchar(100) DEFAULT NULL COMMENT '转让类型。有追、无追',
                                              `proj_source` varchar(20) DEFAULT NULL COMMENT '存量翻单、渠道介绍、自主开发',
                                              `evaluation_subject_id` bigint(20) DEFAULT NULL COMMENT '评估主体ID',
                                              `funds_purpose` text COMMENT '资金用途',
                                              `proj_background` longtext COMMENT '项目背景',
                                              `country` varchar(20) DEFAULT NULL COMMENT '国家',
                                              `province` varchar(20) DEFAULT NULL COMMENT '省份',
                                              `city` varchar(20) DEFAULT NULL COMMENT '城市',
                                              `district` varchar(20) DEFAULT NULL COMMENT '区、县',
                                              `transferor_client_id` bigint(20) DEFAULT NULL COMMENT '转让方。（项目类型为租赁时）',
                                              `lessee_info` json DEFAULT NULL COMMENT '承租人列表',
                                              `creditor_client_id` bigint(20) DEFAULT NULL COMMENT '债权人id',
                                              `creditor_stock_risk_exposure` bigint(20) DEFAULT NULL COMMENT '债权人存量风险敞口',
                                              `debtor_info` json DEFAULT NULL COMMENT '债务人信息。（项目类型为保理时）',
                                              `guarantee_info` json DEFAULT NULL COMMENT '担保人信息',
                                              `pledgor_info` json DEFAULT NULL COMMENT '质押人信息',
                                              `mortgagor_info` json DEFAULT NULL COMMENT '抵押人信息',
                                              `proj_sponsor_user_id` bigint(20) DEFAULT NULL COMMENT '项目主办用户id',
                                              `proj_cosponsor_user_ids` json DEFAULT NULL COMMENT '项目协办方用户id列表',
                                              `create_by` bigint(20) DEFAULT NULL COMMENT '创建人、发起人',
                                              `biz_dept_id` bigint(20) DEFAULT NULL COMMENT '业务部门id',
                                              `biz_dept_leader_id` bigint(20) DEFAULT NULL COMMENT '业务部门负责人id',
                                              `biz_division_leader_id` bigint(20) DEFAULT NULL COMMENT '业务分管领导id',
                                              `risk_control_manager_id` bigint(20) DEFAULT NULL COMMENT '风控经理id',
                                              `legal_manager_user_id` bigint(20) DEFAULT NULL,
                                              `proj_pricing_status` varchar(50) DEFAULT NULL COMMENT '定价状态',
                                              `proj_pricing_process_status` varchar(50) DEFAULT NULL COMMENT '流程状态',
                                              `declared_amount` bigint(20) DEFAULT NULL COMMENT '冗余报价方案字段',
                                              `proj_establish_id` bigint(20) DEFAULT NULL COMMENT '关联的立项ID',
                                              `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                              `update_by` bigint(20) DEFAULT NULL COMMENT '最后更新人id',
                                              `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                                              `version` varchar(40) NOT NULL COMMENT '版本号',
                                              `origin_id` bigint(20) NOT NULL COMMENT '临时数据表id 需要用来比对数据 或者 流程拒绝时全量回写',
                                              `data_create_time` datetime DEFAULT NULL,
                                              `data_create_by` bigint(20) DEFAULT NULL,
                                              `data_update_time` datetime DEFAULT NULL,
                                              `data_update_by` bigint(20) DEFAULT NULL,
                                              `creditor_info` json DEFAULT NULL COMMENT '债权人信息',
                                              `assignor` varchar(200) DEFAULT NULL COMMENT '转让方（转租赁类型时）',
                                              `relation_data_type` varchar(30) DEFAULT NULL COMMENT '数据来源类型，区分普通立项(PROJ_ESTABLISH)和集团授信(GROUP_CREDIT_REVIEW)',
                                              `group_credit_review_id` bigint(20) DEFAULT NULL COMMENT '集团授信评审id',
                                              `remark` varchar(500) DEFAULT NULL COMMENT '备注',
                                              `version_type` tinyint(4) DEFAULT '1' COMMENT '版本标志，0无效，1有效...业务自扩展',
                                              `enterprise_nature` varchar(20) DEFAULT NULL COMMENT '企业性质',
                                              `risk_control_industry_classify` varchar(50) DEFAULT NULL COMMENT '风控行业分类',
                                              PRIMARY KEY (`id`) USING BTREE,
                                              KEY `proj_pricing_lib_proj_sponsor_user_id` (`proj_sponsor_user_id`) USING BTREE COMMENT '主办',
                                              KEY `proj_pricing_proj_pricing_status` (`proj_pricing_status`) USING BTREE COMMENT '立项状态',
                                              KEY `idx_origin_id` (`origin_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7266 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='项目定价基本信息版本表';


